<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF">  "name"</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2">:</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379"> "John Doe"</span></span>
